INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pdp_112', (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pdp-1-1' AND is_deleted = false LIMIT 1), 'incremental-orders-extract', 'Extract orders incrementally with a watermark', 'The nightly copy of Rice Rocket''s orders into the warehouse took two hours as a full extract. The editor holds `pipelines/orders_incremental.py` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that `run_once` reads the watermark of the job `orders`, extracts every order changed at or after the watermark minus `lookback_minutes` (late commits must not be missed), upserts them into `fact_orders`, moves the watermark to the largest `updated_at` it actually read (never the clock; unchanged when nothing was read), and commits the load and the watermark together so a failed load saves neither. Run replays several nights on SQLite, including a late commit and a failed load, and compares the warehouse with the source.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
