INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_112'), 1, 'Follow one late order: it commits after the extraction started, with an `updated_at` a few minutes before the watermark the run leaves behind. Which query of the next run still sees it, and which watermark makes that possible?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_112'), 2, 'Look at `datetime.strptime` and `timedelta` for the start of the window, `max(..., default=...)` for the new watermark, and `with wh:` in Python''s sqlite3, which commits the whole block or rolls it back.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_112'), 3, 'A job that copies payments by `paid_at` might do: `start = last - timedelta(minutes=10)`, `rows = SELECT ... WHERE paid_at >= start ORDER BY paid_at`, `last = max([r.paid_at for r in rows], default=last)`, and inside one `with conn:` block both the upsert of the rows and `UPDATE job_state SET last = ?`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_112'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"read-since","label":"Where this run starts reading, given the watermark","code":"since = (datetime.strptime(watermark, FMT) - timedelta(minutes=lookback_minutes)).strftime(FMT)"},{"id":"extract","label":"The changed orders, oldest change first","code":"rows = src.execute(\n    \"SELECT order_id, status, total_vnd, updated_at FROM orders WHERE updated_at >= ? ORDER BY updated_at, order_id\",\n    (since,),\n).fetchall()"},{"id":"new-watermark","label":"The watermark this run leaves behind","code":"new_watermark = max([r[3] for r in rows], default=watermark)\nnew_watermark = max(new_watermark, watermark)"},{"id":"load-and-commit","label":"Load the rows and save the watermark","code":"with wh:\n    wh.executemany(\n        \"\"\"INSERT INTO fact_orders (order_id, status, total_vnd, updated_at) VALUES (?, ?, ?, ?)\n           ON CONFLICT (order_id) DO UPDATE SET status = excluded.status,\n               total_vnd = excluded.total_vnd, updated_at = excluded.updated_at\"\"\",\n        rows,\n    )\n    wh.execute(\"UPDATE etl_state SET last_updated_at = ? WHERE job = ''orders''\", (new_watermark,))"},{"id":"extract-after-watermark","label":"The changed orders, oldest change first","code":"rows = src.execute(\n    \"SELECT order_id, status, total_vnd, updated_at FROM orders WHERE updated_at > ? ORDER BY updated_at, order_id\",\n    (watermark,),\n).fetchall()","distractor":true},{"id":"load-watermark-first","label":"Load the rows and save the watermark","code":"wh.execute(\"UPDATE etl_state SET last_updated_at = ? WHERE job = ''orders''\", (new_watermark,))\nwh.commit()\nwith wh:\n    wh.executemany(\n        \"\"\"INSERT INTO fact_orders (order_id, status, total_vnd, updated_at) VALUES (?, ?, ?, ?)\n           ON CONFLICT (order_id) DO UPDATE SET status = excluded.status,\n               total_vnd = excluded.total_vnd, updated_at = excluded.updated_at\"\"\",\n        rows,\n    )","distractor":true},{"id":"new-watermark-clock","label":"The watermark this run leaves behind","code":"new_watermark = datetime.now().strftime(FMT)","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
