       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_112'), 'A failed load keeps the old watermark and the next run catches up', '{"lookback_minutes":15,"initial":[[1,"delivered",120000,"2026-11-05 08:00:00"],[2,"delivered",85000,"2026-11-05 09:30:00"],[3,"cancelled",60000,"2026-11-05 10:10:00"],[4,"delivered",150000,"2026-11-05 11:45:00"],[5,"cooking",99000,"2026-11-05 12:00:00"],[6,"placed",45000,"2026-11-05 12:05:00"]],"runs":[{},{"before":[[10,"placed",81000,"2026-11-05 12:06:00"],[11,"placed",39000,"2026-11-05 12:10:00"],[12,"placed",64000,"2026-11-05 12:50:00"]],"fail_on_order":12},{}]}', '{"missing_or_stale":[],"extra":[],"watermark":"2026-11-05 12:50:00","rows_read":[6,null,5],"failed_runs":[2]}', 6, true, false, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_112'), 'A late order with the same updated_at as the watermark, then runs with nothing new', '{"lookback_minutes":15,"initial":[[1,"delivered",120000,"2026-11-05 08:00:00"],[2,"delivered",85000,"2026-11-05 09:30:00"],[3,"cancelled",60000,"2026-11-05 10:10:00"],[4,"delivered",150000,"2026-11-05 11:45:00"],[5,"cooking",99000,"2026-11-05 12:00:00"],[6,"placed",45000,"2026-11-05 12:05:00"]],"runs":[{"after":[[13,"placed",30000,"2026-11-05 12:05:00"]]},{},{}]}', '{"missing_or_stale":[],"extra":[],"watermark":"2026-11-05 12:05:00","rows_read":[6,3,3],"failed_runs":[]}', 6, false, true, 4),
