INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_121'), 1, 'Line up the task log with the database: when did the first attempt''s INSERT commit, and when did Airflow decide the attempt had failed?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_121'), 2, 'Read SQLite''s documentation of the REPLACE conflict resolution: what happens to the existing row, and to the columns the INSERT does not name?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_121'), 3, 'With an upsert guarded by `WHERE excluded.computed_at > restaurant_payouts.computed_at`, follow a replay of a file computed earlier than the row already in the table.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_121');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_121'), 'The payouts task timed out on its first attempt and Airflow retried it:

```text
[2026-11-05 02:10:04] payouts.load  INFO  inserted 412 rows into restaurant_payouts
[2026-11-05 02:10:31] payouts.load  ERROR Task timed out after 30.0 seconds (execution_timeout)
[2026-11-05 02:10:31] payouts.load  INFO  Marking task as UP_FOR_RETRY
[2026-11-05 02:15:32] payouts.load  INFO  inserted 412 rows into restaurant_payouts
```

```sql
SELECT restaurant_id, business_date, count(*) FROM restaurant_payouts
GROUP BY 1, 2 HAVING count(*) > 1;
-- 412 rows
```

Statement: "Retries are safe here because Airflow only retries a task that failed, and a failed attempt has not written anything."', 'single_choice'::question_type, 'False. The first attempt committed its 412 rows at 02:10:04 and then failed afterwards, on the timeout, so the retry inserted them again. Airflow knows that the task failed, not what it had already done. Every task that Airflow (or any orchestrator) may retry has to be idempotent: running it twice with the same input must leave the same result, which a plain INSERT on a table without a natural key cannot do.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_121') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_121'), 'A teammate switched the load to `INSERT OR REPLACE` after adding a unique key on `(restaurant_id, business_date)`:

```sql
-- finance marked the transfer for restaurant 102 at 09:30
SELECT paid_at FROM restaurant_payouts WHERE restaurant_id = 102 AND business_date = ''2026-11-04'';
-- 2026-11-05 09:30:00

INSERT OR REPLACE INTO restaurant_payouts (restaurant_id, business_date, amount_vnd, orders, computed_at)
VALUES (102, ''2026-11-04'', 1980000, 27, ''2026-11-05 02:10:00'');

SELECT paid_at FROM restaurant_payouts WHERE restaurant_id = 102 AND business_date = ''2026-11-04'';
-- NULL
```

Statement: "`OR REPLACE` deletes the conflicting row and inserts a new one, so every column the INSERT does not name, like `paid_at`, comes back as its default."', 'single_choice'::question_type, 'True. SQLite''s REPLACE conflict resolution removes the rows that violate the constraint, then inserts the new row; columns not listed take their defaults (`NULL` here). `INSERT ... ON CONFLICT (...) DO UPDATE SET ...` updates only the columns it names, which is what a load that shares a table with another writer needs. PostgreSQL has no `OR REPLACE`; its `ON CONFLICT DO UPDATE` behaves the same way as SQLite''s upsert.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_121') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_121'), 'Finance replayed Monday''s original file after a corrected computation had been loaded:

```sql
INSERT INTO restaurant_payouts AS t (restaurant_id, business_date, amount_vnd, orders, computed_at)
VALUES (103, ''2026-11-04'', 7310000, 104, ''2026-11-05 02:10:00'')
ON CONFLICT (restaurant_id, business_date) DO UPDATE SET
    amount_vnd = excluded.amount_vnd, orders = excluded.orders, computed_at = excluded.computed_at
WHERE excluded.computed_at > t.computed_at;
-- row in the table before: amount_vnd 7120000, computed_at 2026-11-05 11:00:00
```

Statement: "The row keeps 7,120,000 VND: the incoming row was computed earlier than the one in the table, so the `WHERE` of the `DO UPDATE` skips it, and replaying old files cannot undo a correction."', 'single_choice'::question_type, 'True. The `WHERE` clause of `DO UPDATE` is evaluated against the existing row (`t`) and the proposed one (`excluded`); when it is false the conflicting row is left alone and the statement reports zero rows changed. Comparing a version or timestamp that travels with the data (not the load time) makes the load order-independent: replays, retries and backfills of old partitions can run in any order.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_121') AND order_index = 3)
    RETURNING id
)
