INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_122'), 1, 'Ask three questions of each piece: what makes two rows ''the same payout'', what happens to columns the load does not own, and in which order can two loads of the same day arrive?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_122'), 2, 'Look at a composite `PRIMARY KEY (...)`, `INSERT ... ON CONFLICT (...) DO UPDATE SET col = excluded.col WHERE ...`, and `with wh:` around `executemany`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_122'), 3, 'A daily courier bonus table with one row per courier and day, written by a job and approved by a manager, would use `PRIMARY KEY (courier_id, day)` and `ON CONFLICT (courier_id, day) DO UPDATE SET bonus_vnd = excluded.bonus_vnd, computed_at = excluded.computed_at WHERE excluded.computed_at > courier_bonus.computed_at`, never naming `approved_by`.');
