INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pdp_132', (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pdp-1-3' AND is_deleted = false LIMIT 1), 'menu-file-schema-drift', 'Load menu files that change shape', 'Partner restaurants send menu CSV exports from their POS vendor, and the vendor changes the columns without warning: last night `price` became `unit_price`, moved, and a new `discount_vnd` appeared, and the old positional loader put prices in the wrong column. The editor holds `pipelines/load_menu.py` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that columns are matched by name and known aliases, a file missing a required column is refused without changing the table, new columns are added to the table and reported, rows that do not convert are listed with their line, and more than 5% bad rows refuses the file. Run loads a sequence of files on SQLite and prints each result and the table.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
