INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_132'), 1, 'Feed tonight''s file to your loader in your head column by column: which table column receives `unit_price`, which receives `discount_vnd`, and what tells you the file is missing something the table cannot do without?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_132'), 2, 'Look at a dictionary from every accepted name (`CONTRACT` keys plus `aliases`) to its column, `PRAGMA table_info(...)` for the columns a table has, and `ALTER TABLE ... ADD COLUMN`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_132'), 3, 'A loader for courier shift files with `courier_id` (alias `driver_id`) and `hours` might build `names = {''courier_id'': ''courier_id'', ''driver_id'': ''courier_id'', ''hours'': ''hours''}`, map `header[i].strip().lower()` through it, refuse the file when `courier_id` is not among the mapped values, and `ALTER TABLE shifts ADD COLUMN "bonus" TEXT` when an unknown `bonus` column shows up.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_132'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"resolve-columns","label":"Match each file column to a table column","code":"names = {}\nfor target, spec in CONTRACT.items():\n    for name in [target, *spec[\"aliases\"]]:\n        names[name] = target\nfor i, raw in enumerate(header):\n    key = raw.strip().lower()\n    mapping[i] = names.get(key, key)"},{"id":"missing-required","label":"Refuse a file without a required column","code":"missing = [c for c, spec in CONTRACT.items() if spec[\"required\"] and c not in present]\nif missing:\n    return {\"status\": \"rejected\", \"reason\": \"missing required column: \" + \", \".join(missing)}"},{"id":"convert-row","label":"Convert one row by the contract, or record why not","code":"for i, value in enumerate(row):\n    column = mapping[i]\n    spec = CONTRACT.get(column, {\"type\": \"str\", \"required\": False})\n    try:\n        record[column] = convert(spec[\"type\"], value)\n    except ValueError:\n        error = f\"line {line}: {column} is not {spec[''type'']}: {value!r}\"\n        break\n    if record[column] is None and spec[\"required\"]:\n        error = f\"line {line}: {column} is empty\"\n        break"},{"id":"reject-threshold","label":"Refuse the file when too many rows are bad","code":"if rows and len(bad) / len(rows) > 0.05:\n    return {\"status\": \"rejected\", \"reason\": f\"{len(bad)} of {len(rows)} rows failed checks\"}"},{"id":"new-columns","label":"Add the columns the table does not know yet","code":"known = {r[1] for r in wh.execute(\"PRAGMA table_info(stg_menu_items)\")}\nadded = [c for c in dict.fromkeys(mapping.values()) if c not in known]\nfor column in added:\n    wh.execute(f''ALTER TABLE stg_menu_items ADD COLUMN \"{column}\" TEXT'')"},{"id":"missing-required-as-null","label":"Refuse a file without a required column","code":"missing = [c for c, spec in CONTRACT.items() if spec[\"required\"] and c not in present]\nif missing:\n    print(\"warning: missing \" + \", \".join(missing), file=sys.stderr)","distractor":true},{"id":"new-columns-ignored","label":"Add the columns the table does not know yet","code":"known = {r[1] for r in wh.execute(\"PRAGMA table_info(stg_menu_items)\")}\nadded = []","distractor":true},{"id":"resolve-by-position","label":"Match each file column to a table column","code":"order = list(CONTRACT)\nfor i, raw in enumerate(header):\n    mapping[i] = order[i] if i < len(order) else raw.strip().lower()","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
