INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_141'), 1, 'Count rows before and after the join: how many rows does order 5001 have in `fact_orders`, and how many after joining it to its three order lines?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_141'), 2, 'Write the weekly average as a sum divided by a count. What does averaging seven daily averages do to a day with 40 orders compared with a day with 900?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_141'), 3, 'State the grain in one sentence ("one row per ..."). Which attributes of an order are left once restaurant, customer and date have their own dimensions?');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_141');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_141'), 'An analyst wanted revenue and the number of items per restaurant in one query:

```sql
SELECT r.name, SUM(o.total_vnd) AS revenue, COUNT(i.item_code) AS items
FROM fact_orders o
JOIN fact_order_items i ON i.order_id = o.order_id
JOIN dim_restaurant r ON r.restaurant_sk = o.restaurant_sk
WHERE o.date_key = 20261104
GROUP BY r.name;
-- Pho Ha Noi | revenue 14,950,000 | items 312

SELECT SUM(total_vnd) FROM fact_orders WHERE restaurant_sk = 17 AND date_key = 20261104;
-- 5,380,000
```

Statement: "The revenue column is still right: the join only adds the item columns, and SUM is not affected by the extra rows."', 'single_choice'::question_type, 'False. `fact_orders` has one row per order, `fact_order_items` one row per order line. Joining them repeats each order''s `total_vnd` once per line, so an order with three dishes is counted three times: 14,950,000 against the real 5,380,000. This is the classic fan-out (or chasm) trap: never sum a measure across a join to a finer grain. Aggregate each fact at its own grain first (or sum `line_total_vnd` from the line-level fact) and join the results.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_141') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_141'), 'The operations dashboard shows the weekly average delivery time:

```text
day         orders  avg_minutes
2026-11-02     900         28.0
2026-11-03     880         29.0
...                (5 more days between 850 and 920 orders, 27-30 min)
2026-11-08      40         65.0      <- storm, most restaurants closed
weekly avg_minutes = AVG(avg_minutes) = 33.9
```

Statement: "Averaging the seven daily averages gives the average delivery time of all orders of the week."', 'single_choice'::question_type, 'False. An average is not additive: the storm day weighs as much as a 900-order day, so 40 slow deliveries pull the weekly figure to 33.9 minutes while the true average over about 5,300 orders is close to 29. Store additive measures in the fact (`delivery_minutes` per order, or a sum and a count per day) and compute `SUM(minutes) / SUM(orders)` at query time. The same applies to ratios and percentiles.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_141') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_141'), 'The modeling review proposed this layout:

```text
fact_order_items   grain: one row per order line
  date_key         -> dim_date
  restaurant_sk    -> dim_restaurant
  customer_sk      -> dim_customer
  item_sk          -> dim_menu_item
  order_id         (no dim_order table)
  quantity, line_total_vnd, discount_vnd
```

Statement: "`order_id` stays on the fact as a degenerate dimension: it groups lines into orders for drill-down, and a separate `dim_order` table would only repeat what the other dimensions already describe."', 'single_choice'::question_type, 'True. Once date, restaurant, customer and menu item have their own dimensions, nothing descriptive is left about an order except its number. Kimball calls such a key a degenerate dimension: it lives on the fact row, is used for grouping (`COUNT(DISTINCT order_id)`) and for tracing a figure back to the source, and needs no table of its own. Declaring the grain first (one row per order line) is what makes this decision obvious.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_141') AND order_index = 3)
    RETURNING id
)
