-- challenge chal_coding_pdp_152 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pdp_152', (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pdp-2-2' AND is_deleted = false LIMIT 1), 'restaurant-commission-history', 'Keep the history of restaurant commissions', 'Finance recomputed September''s commission with October''s rates because `dim_restaurant` was overwritten every night. The editor holds `pipelines/dim_restaurant_scd2.py` with its key blocks missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that a change of `district` or `commission_pct` closes the current version on the snapshot''s date and opens a new one, a new `name` corrects every version without creating one, a new restaurant gets its first version, applying the same snapshot twice changes nothing, and `restaurant_sk_at` returns the version valid on a given day (`valid_from <= day < valid_to`). Run applies a series of snapshots on SQLite, then prices orders with the version valid on their day.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
