INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_152'), 1, 'Draw one restaurant''s timeline: two versions with `valid_from` and `valid_to`, and an order on 30 September and one on 1 October. Which version must each order find, and which date ends the first version?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_152'), 2, 'Look at the current row (`is_current = 1`), a tuple comparison of only the tracked attributes, an `UPDATE` that ends a version on the snapshot''s date, and a lookup with `valid_from <= ? AND ? < valid_to`.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_152'), 3, 'A product dimension that tracks `category` but not `description` would do: `if new.description != cur.description: UPDATE ... SET description = ? WHERE product_id = ?`, then `if (new.category,) != (cur.category,): UPDATE ... SET valid_to = :day, is_current = 0 WHERE product_sk = :sk` followed by an INSERT with `valid_from = :day`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_152'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"first-version","label":"A restaurant seen for the first time","code":"if current is None:\n    wh.execute(INSERT_VERSION, {**row, \"valid_from\": snapshot_date})\n    continue"},{"id":"type-1-name","label":"A new name, without a new version","code":"if row[\"name\"] != name:\n    wh.execute(\"UPDATE dim_restaurant SET name = ? WHERE restaurant_id = ?\", (row[\"name\"], row[\"restaurant_id\"]))"},{"id":"detect-change","label":"Has a tracked attribute changed?","code":"changed = (row[\"district\"], row[\"commission_pct\"]) != (district, pct)"},{"id":"close-current","label":"End the version that was valid until now","code":"wh.execute(\"UPDATE dim_restaurant SET valid_to = ?, is_current = 0 WHERE restaurant_sk = ?\", (snapshot_date, sk))"},{"id":"version-on-day","label":"The version that was valid on a given day","code":"row = wh.execute(\n    \"SELECT restaurant_sk FROM dim_restaurant WHERE restaurant_id = ? AND valid_from <= ? AND ? < valid_to\",\n    (restaurant_id, day, day)).fetchone()"},{"id":"close-current-load-day","label":"End the version that was valid until now","code":"wh.execute(\"UPDATE dim_restaurant SET valid_to = ?, is_current = 0 WHERE restaurant_sk = ?\", (date.today().isoformat(), sk))","distractor":true},{"id":"detect-change-all-columns","label":"Has a tracked attribute changed?","code":"changed = (row[\"name\"], row[\"district\"], row[\"commission_pct\"]) != (name, district, pct)","distractor":true},{"id":"version-on-day-current","label":"The version that was valid on a given day","code":"row = wh.execute(\n    \"SELECT restaurant_sk FROM dim_restaurant WHERE restaurant_id = ? AND is_current = 1\",\n    (restaurant_id,)).fetchone()","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_152');
