-- challenge chal_coding_pdp_162 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pdp_162', (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pdp-2-3' AND is_deleted = false LIMIT 1), 'dedup-order-events', 'Load order events exactly once', 'The apps send order events at least once: a phone that misses the acknowledgement resends the same event (same `event_id`, later `ingested_at`), and an offline phone sends yesterday''s events in tonight''s file. The revenue report came out 6% too high, and replaying a broken night crashed the load. The editor holds `pipelines/order_events.py` with its key pieces missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that `load_night` keeps one row per `event_id` from the file (the copy that arrived first), adds only events the `events` table does not have yet, and can load the same file twice without changing anything or failing; and `Q_DAILY_REVENUE` sums `order_paid` amounts per business day in Ho Chi Minh City (UTC+7), whichever night the event arrived. Run loads the test''s nights into SQLite and prints events per type, revenue per day and which copy of an event was kept.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_162');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_162'), 1, 'Write down what makes two rows "the same event". Two copies of one retry share something that two bowls of the same dish in one order do not.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_162'), 2, 'Look at `ROW_NUMBER() OVER (PARTITION BY ... ORDER BY ...)` to keep one row per key inside the file, `INSERT ... SELECT ... ON CONFLICT (...) DO NOTHING` against the primary key for copies loaded on earlier nights, and SQLite''s `date(ts, ''+7 hours'')` for a local day.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_162'), 3, 'Deduplicating page views by `view_id`, keeping the first copy and counting views per local day in Bangkok (UTC+7): `SELECT * FROM (SELECT v.*, ROW_NUMBER() OVER (PARTITION BY view_id ORDER BY received_at) AS n FROM raw_views v) WHERE n = 1`, loaded with `INSERT INTO views ... ON CONFLICT (view_id) DO NOTHING`, and reported with `SELECT date(viewed_at, ''+7 hours'') AS day, COUNT(*) FROM views GROUP BY day`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_162'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"batch-unique","label":"One row per event from tonight''s file","code":"Q_BATCH_UNIQUE = \"\"\"\nSELECT event_id, order_id, event_type, amount_vnd, event_time, ingested_at\nFROM (\n    SELECT s.*, ROW_NUMBER() OVER (PARTITION BY event_id ORDER BY ingested_at, rowid) AS copy\n    FROM staging s\n)\nWHERE copy = 1\n\"\"\""},{"id":"insert-new","label":"Add only events the warehouse has not seen","code":"Q_INSERT_NEW = \"\"\"\nINSERT INTO events (event_id, order_id, event_type, amount_vnd, event_time, ingested_at)\n\"\"\" + Q_BATCH_UNIQUE + \"\"\"\nON CONFLICT (event_id) DO NOTHING\n\"\"\""},{"id":"daily-revenue","label":"Paid revenue per business day in Ho Chi Minh City","code":"Q_DAILY_REVENUE = \"\"\"\nSELECT date(event_time, ''+7 hours'') AS day, SUM(amount_vnd) AS revenue_vnd\nFROM events\nWHERE event_type = ''order_paid''\nGROUP BY day\nORDER BY day\n\"\"\""},{"id":"batch-unique-order-type","label":"One row per event from tonight''s file","code":"Q_BATCH_UNIQUE = \"\"\"\nSELECT event_id, order_id, event_type, amount_vnd, event_time, ingested_at\nFROM (\n    SELECT s.*, ROW_NUMBER() OVER (PARTITION BY order_id, event_type ORDER BY ingested_at, rowid) AS copy\n    FROM staging s\n)\nWHERE copy = 1\n\"\"\"","distractor":true},{"id":"insert-plain","label":"Add only events the warehouse has not seen","code":"Q_INSERT_NEW = \"\"\"\nINSERT INTO events (event_id, order_id, event_type, amount_vnd, event_time, ingested_at)\n\"\"\" + Q_BATCH_UNIQUE","distractor":true},{"id":"revenue-ingest-day","label":"Paid revenue per business day in Ho Chi Minh City","code":"Q_DAILY_REVENUE = \"\"\"\nSELECT date(ingested_at, ''+7 hours'') AS day, SUM(amount_vnd) AS revenue_vnd\nFROM events\nWHERE event_type = ''order_paid''\nGROUP BY day\nORDER BY day\n\"\"\"","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, snippets = EXCLUDED.snippets, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_162');
