       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_162'), 'Loading the same night again changes nothing and does not fail', '{"nights":[[["e-1001-placed",1001,"order_placed",0,"2026-11-05T04:10:00Z","2026-11-05T04:10:02Z"],["e-1001-item-a",1001,"item_added",65000,"2026-11-05T04:11:00Z","2026-11-05T04:11:01Z"],["e-1001-item-b",1001,"item_added",30000,"2026-11-05T04:11:30Z","2026-11-05T04:11:31Z"],["e-1001-paid",1001,"order_paid",95000,"2026-11-05T04:12:00Z","2026-11-05T04:12:01Z"],["e-1001-paid",1001,"order_paid",95000,"2026-11-05T04:12:00Z","2026-11-05T04:12:31Z"],["e-1002-placed",1002,"order_placed",0,"2026-11-05T05:00:00Z","2026-11-05T05:00:01Z"],["e-1002-paid",1002,"order_paid",120000,"2026-11-05T05:00:40Z","2026-11-05T05:01:42Z"],["e-1002-paid",1002,"order_paid",120000,"2026-11-05T05:00:40Z","2026-11-05T05:00:41Z"]],[["e-1001-placed",1001,"order_placed",0,"2026-11-05T04:10:00Z","2026-11-05T04:10:02Z"],["e-1001-item-a",1001,"item_added",65000,"2026-11-05T04:11:00Z","2026-11-05T04:11:01Z"],["e-1001-item-b",1001,"item_added",30000,"2026-11-05T04:11:30Z","2026-11-05T04:11:31Z"],["e-1001-paid",1001,"order_paid",95000,"2026-11-05T04:12:00Z","2026-11-05T04:12:01Z"],["e-1001-paid",1001,"order_paid",95000,"2026-11-05T04:12:00Z","2026-11-05T04:12:31Z"],["e-1002-placed",1002,"order_placed",0,"2026-11-05T05:00:00Z","2026-11-05T05:00:01Z"],["e-1002-paid",1002,"order_paid",120000,"2026-11-05T05:00:40Z","2026-11-05T05:01:42Z"],["e-1002-paid",1002,"order_paid",120000,"2026-11-05T05:00:40Z","2026-11-05T05:00:41Z"]]],"watch":["e-1002-paid"]}', '{"per_type":{"item_added":2,"order_paid":2,"order_placed":2},"revenue":{"2026-11-05":215000},"kept_copy":{"e-1002-paid":"2026-11-05T05:00:41Z"}}', 6, true, false, 2),
