INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pdp_172', (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pdp-3-1' AND is_deleted = false LIMIT 1), 'write-audit-publish-checks', 'Audit the batch before it is published', 'The nightly load now writes tonight''s export to `staging_orders`, audits it, and publishes it to `orders` (read by the dashboards) only when the audit passes. The editor holds `pipelines/order_checks.py` with its key pieces missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that the error checks catch rows missing an id, a restaurant or a time, order ids repeated in the batch or already published, delivered orders without a positive total, and unknown restaurants; the warning check `volume` fires when tonight has fewer than 70% of the median daily rows of the 7 business days before (Ho Chi Minh City time, UTC+7); and `decide` publishes only when no error check fails, reporting warnings without blocking. Run builds the tables in SQLite, audits the batch and prints each check''s failing rows, the decision and the published row count.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
