-- challenge chal_coding_pdp_182 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_pdp_182', (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'python-data-pipelines') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-pdp-3-2' AND is_deleted = false LIMIT 1), 'partition-backfills', 'Recompute commission one business day at a time', '`fact_commission` holds the commission per restaurant per business day (Ho Chi Minh City time, UTC+7) that the monthly invoices read. After a rate fix, the first October backfill appended rows and doubled October, and the nightly job loaded "today in UTC", missing orders placed after midnight local time. The editor holds `pipelines/commission.py` with its key pieces missing, each marked by a `# [ ]` line; some pieces are wrong on purpose. Fill every line so that `run_day` recomputes exactly one business day (18% of the summed subtotal) and gives the same rows when run again, `backfill` runs every day from start to end with both ends included, oldest first, and `nightly` recomputes the `lookback` business days before the run date, so late orders land in their own day. Run executes the test''s steps against SQLite and prints the days each step processed and the final fact table.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = EXCLUDED.is_published, is_deleted = false, updated_at = now();
