INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_182'), 1, 'Pick one order placed at 06:30 in Ho Chi Minh City and one at 01:00: which business day owns each, and what happens to the fact table when the same day is processed twice?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_182'), 2, 'Look at converting a local midnight to UTC with `datetime` and `timedelta`, `DELETE` then `INSERT` for one partition inside one transaction, and a `while` loop over `date` objects with an inclusive end.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_182'), 3, 'Rebuilding daily courier payouts per business day in Jakarta (UTC+7): `start = datetime.fromisoformat(day) - timedelta(hours=7)`, then in one transaction `DELETE FROM payouts WHERE day = ?` and `INSERT INTO payouts SELECT ?, courier_id, SUM(fee) FROM deliveries WHERE delivered_at >= ? AND delivered_at < ? GROUP BY courier_id`; a backfill loops `while d <= end_date`.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode, snippets)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_pdp_182'), 'stdio', 3000, 128, NULL, 'all_or_nothing', '[{"id":"day-bounds","label":"UTC start and end of one business day","code":"def day_bounds(day):\n    start = datetime.fromisoformat(day) - timedelta(hours=7)  # 00:00 in Ho Chi Minh City\n    end = start + timedelta(days=1)\n    return start.strftime(\"%Y-%m-%dT%H:%M:%SZ\"), end.strftime(\"%Y-%m-%dT%H:%M:%SZ\")"},{"id":"replace-day","label":"Recompute one day so a rerun gives the same rows","code":"def run_day(db, day):\n    start, end = day_bounds(day)\n    with db:\n        db.execute(\"DELETE FROM fact_commission WHERE day = ?\", (day,))\n        db.execute(\n            \"\"\"INSERT INTO fact_commission (day, restaurant_id, orders, commission_vnd)\n               SELECT ?, restaurant_id, COUNT(*), CAST(ROUND(SUM(subtotal_vnd) * 0.18) AS INTEGER)\n               FROM orders WHERE placed_at >= ? AND placed_at < ?\n               GROUP BY restaurant_id\"\"\",\n            (day, start, end),\n        )"},{"id":"backfill-range","label":"Every day of the range, both ends included","code":"def backfill(db, start, end):\n    days, d = [], date.fromisoformat(start)\n    while d <= date.fromisoformat(end):\n        run_day(db, d.isoformat())\n        days.append(d.isoformat())\n        d += timedelta(days=1)\n    return days"},{"id":"lookback","label":"The days a nightly run recomputes","code":"def nightly(db, run_date, lookback):\n    last = date.fromisoformat(run_date) - timedelta(days=1)\n    days = [(last - timedelta(days=k)).isoformat() for k in range(lookback - 1, -1, -1)]\n    for day in days:\n        run_day(db, day)\n    return days"},{"id":"backfill-end-excluded","label":"Every day of the range, both ends included","code":"def backfill(db, start, end):\n    days, d = [], date.fromisoformat(start)\n    while d < date.fromisoformat(end):\n        run_day(db, d.isoformat())\n        days.append(d.isoformat())\n        d += timedelta(days=1)\n    return days","distractor":true},{"id":"day-bounds-utc","label":"UTC start and end of one business day","code":"def day_bounds(day):\n    start = datetime.fromisoformat(day)\n    end = start + timedelta(days=1)\n    return start.strftime(\"%Y-%m-%dT%H:%M:%SZ\"), end.strftime(\"%Y-%m-%dT%H:%M:%SZ\")","distractor":true},{"id":"replace-day-append","label":"Recompute one day so a rerun gives the same rows","code":"def run_day(db, day):\n    start, end = day_bounds(day)\n    with db:\n        db.execute(\n            \"\"\"INSERT INTO fact_commission (day, restaurant_id, orders, commission_vnd)\n               SELECT ?, restaurant_id, COUNT(*), CAST(ROUND(SUM(subtotal_vnd) * 0.18) AS INTEGER)\n               FROM orders WHERE placed_at >= ? AND placed_at < ?\n               GROUP BY restaurant_id\"\"\",\n            (day, start, end),\n        )","distractor":true}]'::jsonb)
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
