INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_191'), 1, 'A retry runs the task again from the top. What did the first attempt already leave behind in the table?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_191'), 2, 'Read `start_date` and `catchup` together: which intervals has the scheduler never run when the DAG is switched on?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_191'), 3, 'Look at what the publish task would publish if it ran after a failed quality check, and what the trigger rule `all_success` exists to prevent.');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_191');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_191'), 'The load task appends, and it has retries:

```python
@task(retries=3, retry_delay=timedelta(minutes=5))
def load(day: str):
    rows = extract(day)
    for chunk in batched(rows, 5000):
        warehouse.execute("INSERT INTO orders VALUES ...", chunk)   # one commit per chunk
```

```text
[2026-11-06 02:14:07] load: inserted chunk 1/5
[2026-11-06 02:14:09] load: inserted chunk 2/5
[2026-11-06 02:14:10] ERROR connection reset by peer
[2026-11-06 02:19:10] load: attempt 2 of 4
[2026-11-06 02:19:15] load: inserted chunk 5/5  -> success
```

Statement: "retries=3 makes this task safe: the attempt that failed halfway is simply run again, and the run ends with the right rows."', 'single_choice'::question_type, 'False. The first attempt committed chunks 1 and 2 before the connection dropped; attempt 2 starts from the top and inserts all five chunks, so 10,000 orders are now in the table twice. Retries are only safe for idempotent tasks: delete and rewrite the day (or write to staging and swap) inside one transaction, as in the partition lesson. The misconception is that the orchestrator undoes a failed attempt; it only runs the code again.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_191') AND order_index = 1)
    RETURNING id
)
