WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_191'), 'The DAG was merged in November and switched on:

```python
@dag(schedule="0 2 * * *",
     start_date=pendulum.datetime(2026, 1, 1, tz="Asia/Ho_Chi_Minh"),
     catchup=True)
def nightly_orders(): ...
```

```text
$ airflow dags list-runs nightly_orders --state queued | wc -l
308
```

Statement: "With catchup enabled the scheduler creates a run for every interval since start_date that has not run yet; set catchup=False (or a recent start_date) unless that backfill is intended."', 'single_choice'::question_type, 'True. Catchup means "run every missed interval": from 1 January to early November is about 308 daily intervals, all queued at once against the production database. If history is wanted, run it as an explicit backfill with limited concurrency; otherwise set `catchup=False` (recent Airflow versions default to False, but say it explicitly) or move `start_date` close to today. The misconception is that `start_date` is only a label.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_pdp_191') AND order_index = 2)
    RETURNING id
)
